// Plain-English overview: Iowa's 2027 withholding formula (effective for
// wages paid on or after January 1, 2027, released November 2026), checked
// against all ten of the formula's own worked examples. The 2027 figures are
// generated by tools/state/generate_ia.py; 2025 and 2026 are tested in
// state2025.test.js and statesBatch2.test.js and are unchanged.

const { expect } = require("chai");
const { computeStateWithholdingCents } = require("../src/regulatory/state");
const ia = require("../src/regulatory/state/ia");

const PAY_DATE = "2027-01-08";
const at = (wagesCents, payPeriodsPerYear, form = null, extra = {}) =>
  ia.compute({ taxYear: 2027, wagesCents, payPeriodsPerYear, form, payDate: PAY_DATE, ...extra });

describe("Iowa 2027 (formula effective January 1, 2027: all ten worked examples)", () => {
  const ex = (G, P, form) => at(G, P, { formYear: 2027, ...form });
  const old = (G, P, maritalStatus, allowances) => at(G, P, { formYear: 2023, maritalStatus, allowances });

  it("Ex. 1-2: $2,100 biweekly - other $40 -> $58.68; joint, spouse no earnings $80 -> $37.55", () => {
    expect(ex(2_100_00, 26, { maritalStatus: "other", allowanceCents: 40_00 }).stateCents).to.equal(58_68);
    expect(ex(2_100_00, 26, { maritalStatus: "marriedJointSpouseNoEarnings", allowanceCents: 80_00 }).stateCents).to.equal(37_55);
  });
  it("Ex. 3: $2,100 biweekly head of household $160 -> $44.23 (rounded once: the printed T2 $50.39 is display rounding; $50.39 - $160/26 would be $44.24)", () => {
    const r = ex(2_100_00, 26, { maritalStatus: "headOfHousehold", allowanceCents: 160_00 });
    expect(r.lines).to.include({ T1: 1_325_96, T2: 50_39, column: "B" });
    expect(r.stateCents).to.equal(44_23);
  });
  it("Ex. 4-6: $5,000 monthly -> $144.23 / $98.47 / $112.94 (Ex. 4 and 5 also need the single final rounding)", () => {
    expect(ex(5_000_00, 12, { maritalStatus: "other", allowanceCents: 40_00 }).stateCents).to.equal(144_23);
    expect(ex(5_000_00, 12, { maritalStatus: "marriedJointSpouseNoEarnings", allowanceCents: 80_00 }).stateCents).to.equal(98_47);
    expect(ex(5_000_00, 12, { maritalStatus: "headOfHousehold", allowanceCents: 160_00 }).stateCents).to.equal(112_94);
  });
  it("Ex. 7-10: 2023-or-earlier IA W-4 (allowances x $40; married -> column C amounts)", () => {
    expect(old(2_100_00, 26, "single", 1).stateCents).to.equal(58_68);
    expect(old(2_100_00, 26, "married", 2).stateCents).to.equal(37_55);
    expect(old(5_000_00, 12, "single", 1).stateCents).to.equal(144_23);
    expect(old(5_000_00, 12, "married", 2).stateCents).to.equal(98_47);
  });
  it("each example's T1 and printed T2 line", () => {
    const cases = [
      [2_100_00, 26, "other", 1_584_62, 60_22],
      [2_100_00, 26, "marriedJointSpouseNoEarnings", 1_069_23, 40_63],
      [5_000_00, 12, "other", 3_883_33, 147_57],
      [5_000_00, 12, "marriedJointSpouseNoEarnings", 2_766_67, 105_13],
      [5_000_00, 12, "headOfHousehold", 3_322_92, 126_27],
    ];
    for (const [G, P, maritalStatus, T1, T2] of cases) {
      expect(ex(G, P, { maritalStatus, allowanceCents: 0 }).lines, maritalStatus).to.include({ T1, T2 });
    }
  });
  it("annual deductions: A $13,400, B $20,125, C $26,800; rate 3.80%; $40 legacy allowance", () => {
    const t = ia.TABLES[2027];
    expect(t.rateBp).to.equal(380);
    expect(t.legacyAllowanceCents).to.equal(40_00);
    expect(t.rounding).to.equal("once");
    const { A, B, C } = t.deductionCents.current;
    expect([A.annual, B.annual, C.annual]).to.deep.equal([13_400_00, 20_125_00, 26_800_00]);
    expect(t.deductionCents.legacy).to.deep.equal({ A, B: C });
  });
  it("each printed per-period deduction is the annual figure / periods (daily: / 260)", () => {
    const n = { daily: 260, weekly: 52, biweekly: 26, semimonthly: 24, monthly: 12, annual: 1 };
    for (const set of Object.values(ia.TABLES[2027].deductionCents)) {
      for (const col of Object.values(set)) {
        expect(Object.keys(col)).to.have.members(Object.keys(n));
        for (const [p, v] of Object.entries(col)) expect(v, p).to.equal(Math.round(col.annual / n[p]));
      }
    }
  });
  it("no IA W-4: column A, no allowances", () => {
    const r = at(2_100_00, 26);
    expect(r.formBasis).to.equal("none-on-file-column-a");
    expect(r.stateCents).to.equal(Math.round((2_100_00 - 515_38) * 0.038));
  });
  it("additional withholding is added after T3; exempt withholds nothing", () => {
    expect(at(2_100_00, 26, { formYear: 2027, maritalStatus: "other", allowanceCents: 40_00, additionalWithholdingCents: 10_00 }).stateCents).to.equal(68_68);
    expect(at(2_100_00, 26, { formYear: 2027, exempt: true }).stateCents).to.equal(0);
  });
  it("quarterly pay annualizes, runs steps 1-3 on the annual figures and divides T3 by 4", () => {
    const r = at(15_000_00, 4, { formYear: 2027, maritalStatus: "other", allowanceCents: 40_00 });
    // (60,000 - 13,400) x 3.80% - $40 = $1,730.80; / 4 = $432.70
    expect(r.lines.T3).to.equal(432_70);
  });
  it("T3 never goes below zero", () => {
    expect(at(400_00, 26, { formYear: 2027, maritalStatus: "other", allowanceCents: 1_000_00 }).stateCents).to.equal(0);
  });
  it("applies to wages paid on or after 2027-01-01: an earlier pay date throws", () => {
    expect(() => at(2_100_00, 26, null, { payDate: "2026-12-31" })).to.throw(/no sourced Iowa withholding for pay date 2026-12-31 \(these figures apply from 2027-01-01\)/);
    expect(at(2_100_00, 26, null, { payDate: "2027-01-01" }).stateCents).to.be.greaterThan(0);
  });
  it("is reachable through computeStateWithholdingCents for tax year 2027", () => {
    const r = computeStateWithholdingCents({
      state: "IA",
      taxYear: 2027,
      grossPayCents: 2_100_00,
      federalTaxableWagesCents: 2_100_00,
      payPeriodsPerYear: 26,
      form: { formYear: 2027, maritalStatus: "headOfHousehold", allowanceCents: 160_00 },
      payDate: PAY_DATE,
    });
    expect(r.stateCents).to.equal(44_23);
  });
  it("2026 is unchanged: still rounded per step", () => {
    expect(ia.TABLES[2026].rounding).to.equal("perStep");
    expect(ia.TABLES[2026].deductionCents.current.A.annual).to.equal(13_000_00);
    const r = ia.compute({ taxYear: 2026, wagesCents: 2_100_00, payPeriodsPerYear: 26, payDate: "2026-12-31",
      form: { formYear: 2026, maritalStatus: "headOfHousehold", allowanceCents: 160_00 } });
    expect(r.stateCents).to.equal(45_15);
  });
  it("2025 cites archived copies, not the reused media/61 URL", () => {
    for (const s of ia.TABLES[2025].sources) expect(s).to.match(/https:\/\/web\.archive\.org\/web\/\d{14}id_\//);
  });
});
